Solution





Using a set makes the chosen nodes distinct: a hub that is named twice counts once.
def acquaintance_immunization(G, fraction, rng):
    nodes = list(G.nodes())
    k = int(round(fraction * len(nodes)))
    chosen = set()
    while len(chosen) &lt; k:
        v = nodes[rng.integers(len(nodes))]
        nbrs = list(G.neighbors(v))
        if nbrs:
            chosen.add(nbrs[rng.integers(len(nbrs))])
    return list(chosen)

